import * as React from "react";
import { Link } from "wouter";
import { ArrowUpRightIcon } from "lucide-react";

import { cn } from "@/lib/utils";
import { useTheme } from "@/components/theme-provider";
import type { BlockItem } from "@/docs/catalog";

/** Static screenshot of a block — generated by scripts/block-thumbs.mjs. */
export function BlockThumb({ slug, title, eager, className }: { slug: string; title: string; eager?: boolean; className?: string }) {
  const { resolvedTheme } = useTheme();
  const [state, setState] = React.useState<"loading" | "ready" | "missing">("loading");
  const src = `/images/blocks/${slug}${resolvedTheme === "dark" ? ".dark" : ""}.webp`;
  React.useEffect(() => setState("loading"), [src]);
  return (
    <div className={cn("relative aspect-[16/10] overflow-hidden bg-tile", className)}>
      {state !== "missing" && (
        <img
          key={src}
          src={src}
          alt={`${title} block preview`}
          width={880}
          height={550}
          loading={eager ? "eager" : "lazy"}
          decoding="async"
          draggable={false}
          ref={(el) => {
            if (el?.complete && el.naturalWidth > 0) setState("ready");
          }}
          onLoad={() => setState("ready")}
          onError={() => setState("missing")}
          className={cn("size-full object-cover object-top transition-opacity duration-300", state === "ready" ? "opacity-100" : "opacity-0")}
        />
      )}
      {state === "missing" && <div className="absolute inset-0 grid place-items-center font-code text-xs text-faint">{slug}</div>}
    </div>
  );
}

/** Gallery card: thumbnail in a hairline frame, title and slug beneath. */
export function BlockCard({ block, eager }: { block: BlockItem; eager?: boolean }) {
  return (
    <Link href={`/blocks/${block.slug}`} className="group/block site-focus flex flex-col gap-3 rounded-3xl">
      <div className="overflow-hidden rounded-3xl border border-hairline transition-colors duration-200 group-hover/block:border-faint">
        <BlockThumb slug={block.slug} title={block.title} eager={eager} className="transition-transform duration-500 ease-out group-hover/block:scale-[1.02]" />
      </div>
      <div className="flex items-start justify-between gap-3 px-1">
        <div className="min-w-0">
          <h3 className="truncate text-sm font-semibold tracking-[-0.01em] text-ink">{block.title}</h3>
          <p className="mt-0.5 line-clamp-1 text-sm text-pencil">{block.description}</p>
        </div>
        <ArrowUpRightIcon className="mt-0.5 size-4 shrink-0 text-faint transition-colors group-hover/block:text-ink" />
      </div>
    </Link>
  );
}
